<script setup>
import figureForms from '../services/figure_forms.json'
import {ref,watch,onMounted,onUnmounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import {Search,SlidersHorizontal,ArrowLeft,ArrowRight} from 'lucide-vue-next';import {useArchive} from '../stores/archive';import {api} from '../services/api';import FigureCard from '../components/FigureCard.vue'
const route=useRoute(),router=useRouter(),store=useArchive(),items=ref([]),total=ref(0),loading=ref(false),error=ref(''),lines=ref([]),natural=ref(''),warnings=ref([])
const filters=ref({q:'',manufacturer_id:'',product_line_id:'',scale:'',year:'',height_max:'',franchise:'',character:'',figure_form:''}),page=ref(1)
let sequence=0
async function load(){const current=++sequence;loading.value=true;error.value='';try{const p=new URLSearchParams({...Object.fromEntries(Object.entries(route.query).filter(([,v])=>v!=='')),page_size:24});const r=await api('/figures?'+p);if(current===sequence){items.value=r.items;total.value=r.total;page.value=r.page}}catch(e){if(current===sequence)error.value=e.message}finally{if(current===sequence)loading.value=false}}
function apply(p=1){warnings.value=[];router.push({path:'/figures',query:{...Object.fromEntries(Object.entries(filters.value).filter(([,v])=>v!=='')),page:p}})}
watch(()=>route.query,()=>{for(const k in filters.value)filters.value[k]=route.query[k]||'';load()},{immediate:true})
function onCatalogUpdated(){load();store.load()}
onMounted(async()=>{window.addEventListener('catalog-updated',onCatalogUpdated);try{lines.value=await api('/product-lines')}catch{}})
onUnmounted(()=>window.removeEventListener('catalog-updated',onCatalogUpdated))
async function ask(){loading.value=true;error.value='';try{const r=await api('/search/natural-language',{method:'POST',body:{query:natural.value}});items.value=r.items;total.value=r.total;warnings.value=r.warnings||[];page.value=1;if(!r.warnings?.some(x=>x.includes('지원하지')||x.includes('실패')))await router.push({path:'/figures',query:{...r.filters,page:1}})}catch(e){error.value=e.message}finally{loading.value=false}}
</script>
<template>
 <section class="page-heading"><p class="eyebrow">THE ARCHIVE</p><h1>피규어 아카이브<span class="count">{{total}}</span></h1><p>공식 자료를 바탕으로, 더 정확하게 찾아보세요.</p></section>
 <div class="catalog-layout"><aside class="filter-panel"><h3><SlidersHorizontal :size="17"/> 상세 필터</h3><form @submit.prevent="apply()"><label>제조사<select v-model="filters.manufacturer_id"><option value="">전체 제조사</option><option v-for="m in store.makers" :key="m.id" :value="m.id">{{m.name_ko}} ({{m.count}})</option></select></label><label>제품 라인<select v-model="filters.product_line_id"><option value="">전체 라인</option><option v-for="l in lines.filter(x=>!filters.manufacturer_id||x.manufacturer_id==filters.manufacturer_id)" :key="l.id" :value="l.id">{{l.name}}</option></select></label><label>작품<input v-model="filters.franchise" placeholder="작품명"></label><label>캐릭터<input v-model="filters.character" placeholder="확인된 캐릭터명"></label><label>피규어 형태<select v-model="filters.figure_form"><option value="">전체 형태</option><option v-for="(label,code) in figureForms" :key="code" :value="code">{{label}}</option></select></label><label>스케일<select v-model="filters.scale"><option value="">전체 스케일</option><option>1/4</option><option>1/6</option><option>1/7</option><option>1/8</option><option>1/12</option></select></label><label>발매 연도<input v-model="filters.year" type="number" min="1950" max="2100" placeholder="예: 2027"></label><label>최대 높이 (mm)<input v-model="filters.height_max" type="number" min="1" placeholder="예: 150"></label><button class="button full">필터 적용</button><button type="button" class="text-link reset" @click="router.push('/figures')">필터 초기화</button></form><p class="fine-print">미확인 사양은 해당 조건 검색에서 제외합니다.</p></aside>
 <div class="catalog-results"><form class="search-bar" @submit.prevent="apply()"><Search :size="20"/><input v-model="filters.q" placeholder="제품명 또는 작품명 검색" aria-label="제품명 검색"><button>검색</button></form><form class="natural-search" @submit.prevent="ask"><label for="natural">문장으로 찾기</label><div><input id="natural" v-model="natural" placeholder="예: 굿스마일 컴퍼니 150mm 이하 피규어" required><button :disabled="loading">조건 검색 ↗</button></div></form><p v-for="w in warnings" :key="w" class="notice">{{w}}</p><p v-if="loading" role="status" class="empty">공식 제품 정보를 불러오는 중…</p><p v-else-if="error" role="alert" class="error">{{error}}</p><div v-else-if="items.length" class="figure-grid catalog-grid"><FigureCard v-for="f in items" :key="f.id" :figure="f"/></div><div v-else class="empty"><h3>검색 결과가 없습니다.</h3><p>필터를 줄이거나 원문 제품명으로 검색해 보세요.</p></div><div class="pagination"><button @click="apply(page-1)" :disabled="page<=1||loading"><ArrowLeft :size="16"/> 이전</button><span>{{page}} / {{Math.max(1,Math.ceil(total/24))}}</span><button @click="apply(page+1)" :disabled="page*24>=total||loading">다음 <ArrowRight :size="16"/></button></div></div></div>
</template>
